      `CLAIM_OPENED sheet=${sheet} by=wes person=Ada amount=30.00 date=2026-03-10 number=3`,
      `ROLLUP sheet=${sheet} by=wes person=Ada claimed=62.00 due-total=6.20 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=wes claimed-total=62.00 due-total=6.20 overdue-total=0.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=30.00 date=2026-03-10 number=3 due=3.00`,
      `CLAIM_SETTLED sheet=${sheet} by=uma person=Ada amount=11.00 date=2026-03-10 number=1 due=1.10`,
      `CLAIM_PENDING sheet=${sheet} by=uma person=Ada amount=21.00 date=2026-03-10 number=2`
    ]);
  });
